public static class GameLuaRegistryGcPublicationTests {
 static int scenarios,assertions,olderAssertions;
 static readonly List<object> checks=new List<object>(),receipts=new List<object>();
 static void Check(bool value,string why){assertions++;if(!value)throw new Exception(why);}
 static void Eq<T>(T expected,T actual,string why){Check(EqualityComparer<T>.Default.Equals(expected,actual),why+" expected="+expected+" actual="+actual);}
 static void Same(object expected,object actual,string why){Check(Object.ReferenceEquals(expected,actual),why);}
 static void Missing(uint at,Action action,string why){try{action();}catch(MissingContract error){Eq(at,error.Address,why);return;}throw new Exception("Expected Unsupported: "+why);}
 static void Test(string name,Action action){int before=assertions;action();scenarios++;checks.Add(new Dictionary<string,object>{{"name",name},{"assertions",assertions-before}});}
 static Dictionary<string,object> Call(OwnLuaCallbackResult r){return new Dictionary<string,object>{{"bridge_status",r.BridgeStatus},{"lua_status",r.LuaStatus},{"stage_rva",r.StageRva},{"published_mask",r.PublishedMask},{"callback_calls",r.CallbackCalls},{"logger_calls",r.LoggerCalls},{"resolver_calls",r.ResolverCalls},{"entry_top",r.EntryTop},{"exit_top",r.ExitTop},{"last_measured_local_top",r.FailureLocalTop},{"host_status",r.HostStatus},{"flags",r.Flags},{"fixture_id",r.FixtureId},{"context_token",r.ContextToken},{"host_failure",r.HostFailure},{"host_failure_rva",r.HostFailureRva},{"engine_read_rva",r.EngineReadRva}};}
 static Dictionary<string,object> Audit(OwnLuaGcAudit a){return new Dictionary<string,object>{{"list_entered",a.ListEntered},{"list_completed",a.ListCompleted},{"object_entered",a.ObjectEntered},{"object_completed",a.ObjectCompleted},{"fixture_userdata_created",a.FixtureUserdataCreated},{"own_buffer_allocations",a.OwnBufferAllocations},{"own_buffer_free_calls",a.OwnBufferFreeCalls},{"own_buffer_free_successes",a.OwnBufferFreeSuccesses},{"live_own_buffers",a.LiveOwnBuffers},{"unsupported_callbacks",a.UnsupportedCallbacks},{"close_callbacks",a.CloseCallbacks},{"fields_unchanged_checks",a.FieldsUnchangedChecks},{"last_failure_rva",a.LastFailureRva},{"last_callback_return",a.LastCallbackReturn},{"context_token",a.ContextToken}};}
 static void Remember(OwnLuaRegistryResult r){receipts.Add(new Dictionary<string,object>{{"registry",new Dictionary<string,object>{{"call",Call(r.Call)},{"phase",r.Phase},{"registry_published_mask",r.RegistryPublishedMask},{"observed_mask",r.ObservedMask},{"registry_types",r.RegistryTypes},{"luaglue_alias",r.LuaGlueAlias},{"gc_closure_match_mask",r.GcClosureMatchMask},{"native_return_byte",r.NativeReturnByte}}}});}
 static OwnLuaGcAudit ReadAudit(OwnLuaCallbackBinding b){var a=b.ReadGcAudit();receipts.Add(new Dictionary<string,object>{{"gc_audit",Audit(a)}});Same(a,b.LastGcAudit,"Actual pure audit receipt retained");Eq(b.Token,a.ContextToken,"Audit belongs to same live context");return a;}
 static void Closed(OwnLuaCallbackBinding b){Check(b.IsClosed&&b.CloseResult!=null,"Real close returned and context was invalidated");Check(b.CloseGcAudit!=null&&b.CloseGcAuditFailure==null,"Actual GC audit captured before native context release");receipts.Add(new Dictionary<string,object>{{"close",Call(b.CloseResult)},{"close_gc_audit",Audit(b.CloseGcAudit)}});Eq(b.Token,b.CloseGcAudit.ContextToken,"Close audit keeps original context identity");Eq(-1,b.CloseResult.LuaStatus,"Close-internal Lua status remains unobserved");Check((b.CloseResult.Flags&16)!=0,"Caller observed actual lua_close return");}
 sealed class Scope:IDisposable {
  internal readonly OwnLuaJit204Runtime Runtime=OwnLuaJit204Runtime.OpenOwnProfile();
  internal readonly WorldEngine World=new WorldEngine();
  internal readonly Field<WorldEngine> EngineGlobal=new Field<WorldEngine>();
  internal readonly GameReachedGoalLuaService Service;
  internal readonly OwnLuaCallbackContext Context;
  readonly List<OwnLuaJit204State> owned=new List<OwnLuaJit204State>();
  internal OwnLuaCallbackBinding Binding;
  internal Scope(){EngineGlobal.Write(World);Service=GameLuaServiceInitializationContracts.PublishOwnColdService(World,new Invocation());Context=new OwnLuaCallbackContext(Service,EngineGlobal,null);Runtime.SelectOwnRegistry(Context);}
  internal OwnLuaJit204State Track(OwnLuaJit204State state){if(state!=null&&!owned.Contains(state))owned.Add(state);return state;}
  internal OwnLuaJit204State Current{get{return Service.Lua00.Read(0) as OwnLuaJit204State;}}
  internal void Glue(){
   var call=new GameLuaGlueInitializationInvocation();try{Missing(0x25762b,delegate{GameLuaServiceInitializationContracts.InitializeLuaGluePrefix0F2E00(Service,GameLuaLibraryBindings.ResolveOwn(Runtime),Runtime,Context,call);},"Real prior definition prefix reaches its retained boundary");}finally{Binding=call.Binding;Track(Current);}
   Check(call.Glue!=null&&call.Glue.Call.LuaStatus==0&&call.Glue.PreparedCount==11&&call.Glue.LoadedCount==11&&call.Glue.ExecutedCount==11,"Registry prerequisite is eleven actually prepared, loaded and called definitions");Same(Binding,Current.CallbackBinding,"Shared real VM owns its binding");Same(null,Context.OwnSink,"No fake logger supplied");
  }
  internal OwnLuaRegistryResult Registry(){var r=Binding.PublishLuaGlueRegistry();Remember(r);Complete(r);return r;}
  internal OwnLuaCallbackResult Fixture(int id){var r=Binding.ExecuteFixture((OwnLuaCallbackFixture)id);receipts.Add(new Dictionary<string,object>{{"fixture",Call(r)}});Eq((uint)id,r.FixtureId,"Actual fixed fixture identity");Check(r.LoggerCalls==0&&r.EngineReadRva==0,"GC fixture never supplies a logger success path");return r;}
  public void Dispose(){for(int n=owned.Count-1;n>=0;n--)owned[n].Dispose();Runtime.Dispose();Check(Runtime.ActiveStateCount==0&&Runtime.CloseFailure==null,"Every tracked real VM closed without lifecycle failure");Check(Runtime.ModuleUnloadObserved,"Pinned OWN modules released after all states close");}
 }
 static void Complete(OwnLuaRegistryResult r){
  Check(r.Call.BridgeStatus==7&&r.Call.StageRva==0x257707,"Actual registry prefix stops before unknown feature flag");Check(r.Call.LuaStatus==0&&(r.Call.Flags&3)==0,"Normal Unsupported boundary creates no Lua error");Eq(3u,r.Phase,"Registry boundary phase");Eq(15u,r.RegistryPublishedMask,"Four actual registry writes returned");Eq(15u,r.ObservedMask,"Four OWN raw registry observations completed");Eq(4,r.RegistryTypes.Length,"Four registry slots observed");foreach(int type in r.RegistryTypes)Eq(5,type,"Actual registry value is table");Eq(1,r.LuaGlueAlias,"Registry -1 is the same actual __luaglue table");Eq(3u,r.GcClosureMatchMask,"Both __gc values match real bridge C closures");Eq(4u,r.Call.ResolverCalls,"Four independent live registry reads occurred");Eq(-1,r.NativeReturnByte,"Native return remains unknown");Check(r.Call.LoggerCalls==0&&r.Call.CallbackCalls==0,"Publication does not execute finalizers or logger");
 }
 static void FixtureOk(OwnLuaCallbackResult r){Check(r.BridgeStatus==0&&r.LuaStatus==0,"Fixed real Lua operation returned normally");}
 static void CallbackUnsupported(OwnLuaCallbackResult r,uint at){Eq(7u,r.BridgeStatus,"Unknown callback contract remains Unsupported");Eq(at,r.StageRva,"Stopped before unknown dereference or unowned free");Check(r.LuaStatus>0&&(r.Flags&3)==3,"Actual GC error stays inside native protection with retained error object");}
 static void NoFree(OwnLuaGcAudit a){Check(a.OwnBufferAllocations==0&&a.OwnBufferFreeCalls==0&&a.OwnBufferFreeSuccesses==0&&a.LiveOwnBuffers==0,"Unknown/foreign fixture neither allocates nor frees an invented owned target");}
 public static Dictionary<string,object> Run(){
  scenarios=assertions=olderAssertions=0;checks.Clear();receipts.Clear();
  Test("New service entry publishes four registry values without setting readiness",delegate{
   using(var s=new Scope()){
    s.Service.Initialized58.Forget();var call=new GameLuaRegistryInitializationInvocation();try{Missing(0x257707,delegate{GameLuaServiceInitializationContracts.InitializeLuaRegistryPrefix0F2E00(s.Service,GameLuaLibraryBindings.ResolveOwn(s.Runtime),s.Runtime,s.Context,call);},"New entry stops at feature-flag boundary");}finally{s.Binding=call.Binding;s.Track(s.Current);}
    Check(call.Registry!=null,"Actual registry receipt retained");Remember(call.Registry);Complete(call.Registry);Eq(0x257707u,call.Native.At,"Service invocation records exact stop");Check(call.GluePrefix.Glue!=null&&call.GluePrefix.Glue.ExecutedCount==11,"Real defining chunks precede registry publication");Same(s.Binding,s.Current.CallbackBinding,"One actual state and binding");Same(s.Service,s.Binding.Context.Service,"Same mutable service");Same(s.Service,GameReachedGoalLogEngine.ForWorldEngine(s.World).LuaService68.Read(0),"Same Engine publication");Eq(1L,s.Runtime.NativeNewStateCalls,"Only one real VM created");Eq(5L,s.Runtime.NativePCallZeroCalls,"Core initialization ran once");Missing(0,delegate{s.Service.Initialized58.Read(0);},"Unknown readiness remains unknown");Same(null,s.Context.OwnSink,"No OWN logger adaptation");var a=ReadAudit(s.Binding);Check(a.ListEntered==0&&a.ObjectEntered==0&&a.FixtureUserdataCreated==0,"Publishing closures is not running them");Eq(-1,a.LastCallbackReturn,"No finalizer return fabricated");
   }
  });
  Test("Registry continuation retains captured VM after service Lua00 replacement",delegate{
   using(var s=new Scope()){
    s.Glue();var first=s.Current;ulong token=s.Binding.Token;var second=s.Track(s.Runtime.NewState(0));Check(second!=null,"Second real VM created for identity check");int secondTop=second.GetTop(0);s.Service.Lua00.Write(second);var r=s.Registry();Eq(token,r.Call.ContextToken,"Registry writes belong to original bound VM");Same(second,s.Service.Lua00.Read(0),"Continuation does not rewrite current service Lua00");Eq(secondTop,second.GetTop(0),"Unbound replacement VM stack unchanged");Check(first.IsAlive&&second.IsAlive&&s.Runtime.ActiveStateCount==2,"Both real state owners remain live");Same(null,second.CallbackBinding,"Replacement VM did not acquire old callbacks");Eq((byte)0,s.Service.Initialized58.Read(0),"Known readiness is not set by continuation");first.Dispose();second.Dispose();Eq(2L,s.Runtime.NativeCloseCalls,"Both exact real VM identities actually closed");Closed(s.Binding);
   }
  });
  Test("Unknown live registry stops after getglobal before first registry store",delegate{
   using(var s=new Scope()){
    s.Glue();s.Context.Registry422888.Forget();var r=s.Binding.PublishLuaGlueRegistry();Remember(r);Eq(7u,r.Call.BridgeStatus,"Unknown registry is not replaced by a default");Eq(0x25763fu,r.Call.StageRva,"First actual live registry read fails");Eq(1u,r.Call.ResolverCalls,"No later registry read attempted");Check(r.Call.LuaStatus>0&&(r.Call.Flags&3)==3,"OWN protected failure retains actual Lua error");Check(r.RegistryPublishedMask==0&&r.ObservedMask==0&&r.GcClosureMatchMask==0,"No registry publication or observation fabricated");foreach(int type in r.RegistryTypes)Eq(-1,type,"Unobserved registry type remains unknown");Eq(-1,r.LuaGlueAlias,"Unobserved alias remains unknown");Eq(-1,r.NativeReturnByte,"No native return invented");Missing(0,delegate{s.Context.Registry422888.Read(0);},"Unknown registry field remains unknown");Eq((byte)0,s.Service.Initialized58.Read(0),"Failure leaves readiness zero");
   }
  });
  Test("Real collect finalizes owned empty chain and null object without field clearing",delegate{
