    s.Glue();s.Registry();FixtureOk(s.Fixture(13));var a=ReadAudit(s.Binding);Check(a.ListEntered==1&&a.ListCompleted==1&&a.ObjectEntered==0,"Actual list finalizer returned during collection");Check(a.OwnBufferAllocations==1&&a.OwnBufferFreeCalls==1&&a.OwnBufferFreeSuccesses==1&&a.LiveOwnBuffers==0,"Actual owned 16-byte allocation freed once by finalizer");FixtureOk(s.Fixture(14));a=ReadAudit(s.Binding);Check(a.ListEntered==1&&a.ListCompleted==1&&a.ObjectEntered==1&&a.ObjectCompleted==1,"Both actual finalizers completed through GC");Eq(2u,a.FixtureUserdataCreated,"Two real fixture userdata objects");Eq(2u,a.FieldsUnchangedChecks,"Callback fields were observed unchanged");Eq(0,a.LastCallbackReturn,"Normal finalizer actually returned zero");Check(a.CloseCallbacks==0&&a.UnsupportedCallbacks==0,"Explicit collect is distinct from close callbacks");s.Current.Dispose();Closed(s.Binding);Eq(0u,s.Binding.CloseGcAudit.CloseCallbacks,"Already finalized fixtures do not run again at close");Eq(1u,s.Binding.CloseGcAudit.OwnBufferFreeSuccesses,"Close does not repeat successful buffer free");
   }
  });
  Test("Nonempty chain and nonnull object stop before unknown virtual slot reads",delegate{
   for(int id=18;id<=19;id++)using(var s=new Scope()){
    s.Glue();s.Registry();uint at=id==18?0x256170u:0x2561b5u;CallbackUnsupported(s.Fixture(id),at);var a=ReadAudit(s.Binding);Eq(at,a.LastFailureRva,"Audit retains precise pre-dereference failure");Eq(1u,a.UnsupportedCallbacks,"One actual unsupported finalizer");Eq(-1,a.LastCallbackReturn,"Failed callback never claimed a return");if(id==18)Check(a.ListEntered==1&&a.ListCompleted==0,"Nonempty list did not execute a fake destructor");else Check(a.ObjectEntered==1&&a.ObjectCompleted==0,"Nonnull object did not execute a fake destructor");NoFree(a);
    if(id==18){
     int errorTop=s.Current.GetTop(0);Check(errorTop>0,"Actual failed GC retains an error object");var refused=s.Binding.ExecuteFixture((OwnLuaCallbackFixture)17);receipts.Add(new Dictionary<string,object>{{"post_failure_admission",Call(refused)}});Eq(17u,refused.FixtureId,"Attempted fixed unknown-userdata fixture");Check(refused.BridgeStatus==7&&refused.LuaStatus==-1&&refused.StageRva==0,"Nonempty entry stack refuses fixture before protected execution");Check(refused.CallbackCalls==0&&refused.LoggerCalls==0&&refused.ResolverCalls==0&&refused.Flags==0,"Admission refusal invokes no callback or synthetic Lua error");Eq(errorTop,refused.EntryTop,"Admission observes retained stack");Eq(errorTop,refused.ExitTop,"Admission leaves retained stack unchanged");Eq(errorTop,s.Current.GetTop(0),"Same VM still owns the actual error prefix");a=ReadAudit(s.Binding);Check(a.FixtureUserdataCreated==1&&a.ListEntered==1&&a.ListCompleted==0&&a.UnsupportedCallbacks==1,"Refused next fixture creates no userdata or finalizer");Eq(at,a.LastFailureRva,"Original GC failure audit remains authoritative");NoFree(a);
    }
