   using(var s=new Scope()){
    s.Glue();s.Registry();CallbackUnsupported(s.Fixture(20),0x25618f);var a=ReadAudit(s.Binding);Eq(0x25618fu,a.LastFailureRva,"Unowned target rejected at free boundary");Check(a.ListEntered==1&&a.ListCompleted==0&&a.UnsupportedCallbacks==1,"No successful list return for foreign buffer");NoFree(a);
   }
   using(var s=new Scope()){
    s.Glue();s.Registry();FixtureOk(s.Fixture(17));var a=ReadAudit(s.Binding);Check(a.ListEntered==0&&a.UnsupportedCallbacks==0,"Deferred foreign userdata has not yet called finalizer");s.Current.Dispose();Closed(s.Binding);a=s.Binding.CloseGcAudit;Check(a.ListEntered==1&&a.ListCompleted==0&&a.CloseCallbacks==1&&a.UnsupportedCallbacks==1,"Actual close attempted and retained foreign userdata failure");Eq(0x256162u,a.LastFailureRva,"Unknown userdata rejected before original field read");Eq(-1,a.LastCallbackReturn,"Close cannot turn failure into callback return");Eq(7u,s.Binding.CloseResult.BridgeStatus,"Close receipt retains swallowed callback Unsupported");Eq(0x256162u,s.Binding.CloseResult.StageRva,"Close receipt keeps callback failure address");NoFree(a);Check(!s.Current.IsAlive&&s.Runtime.NativeCloseCalls==1,"lua_close actually returned despite internal callback error");
   }
