  return new Dictionary<string,object>{{"status","passed-own-lua-registry-gc-prefix"},{"scenarios",scenarios},{"new_scenarios",scenarios-1},{"selected_older_regressions",1},{"assertions",assertions},{"new_assertions",assertions-olderAssertions},{"selected_older_assertions",olderAssertions},{"old_whole_suites_run",0},{"targeted_checks",checks},{"registry_gc_receipts",receipts},{"expected_unsupported",0x257707},{"own_userdata_fixtures",true},{"own_allocator_adaptation",true},{"actual_gc_and_close_distinguished",true},{"post_failure_fixture_admission_tested",true},{"allocator_address_reuse_observed",false},{"registry_each_read_value_history_recorded",false},{"registry_midcall_mutation_tested",false},{"native_return_known",false},{"full_native_luaglue_complete",false},{"native_service_initialization_completed",false},{"unknown_dynamic_destructors_executed",false},{"original_allocator_abi_verified",false},{"defined_function_bodies_invoked",false},{"original_exception_cleanup_equivalent",false},{"original_executed",false},{"physical_mouse",false},{"native_decoding",false},{"native_playback",false},{"gameplay_accepted",false}};
